const http = require("http");
const fs = require("fs");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const seen = [];
const W = "/accounts/acc123/workers/workers/my-worker";
const D = W + "/previews/feat/deployments/latest";
const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => { body += c; });
  req.on("end", () => {
    const path = req.url.split("?")[0];
    seen.push({ method: req.method, path, body });
    let result = {};
    if (path.includes("/previews/")) result = { id: "dep-1", urls: [], env: {} };
    else if (path.endsWith(W)) result = { name: "my-worker", preview_defaults: { env: {} } };
    else if (path.endsWith("/memberships")) result = [{ account: { id: "acc123", name: "acc" } }];
    else if (path.endsWith("/accounts")) result = [{ id: "acc123", name: "acc" }];
    else if (path.endsWith("/tokens/verify")) result = { status: "active" };
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result }));
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const cwd = fs.mkdtempSync("/tmp/proj-");
  const env = Object.assign({}, process.env, {
    CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4",
    CLOUDFLARE_API_TOKEN: "test-token",
    CLOUDFLARE_ACCOUNT_ID: "acc123",
    GITHUB_HEAD_REF: "feat",
    WRANGLER_SEND_METRICS: "false",
    NO_COLOR: "1",
    HOME: "/tmp"
  });
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "preview", "secret", "put", "MY_SECRET", "--worker-name", "my-worker"], { cwd, env, stdio: ["pipe", "pipe", "pipe"] });
  let out = "";
  child.stdout.on("data", (d) => { out += d; });
  child.stderr.on("data", (d) => { out += d; });
  child.stdin.end("s3cret\n");
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler timed out: " + out.slice(-500)); }, 75000);
  child.on("close", (status) => {
    clearTimeout(timer);
    server.close();
    const patches = seen.filter((r) => r.method === "PATCH");
    const toDeployment = patches.find((r) => r.path.endsWith(D));
    const toSettings = patches.find((r) => r.path.endsWith(W));
    if (toSettings && !toDeployment) {
      let b = {};
      try { b = JSON.parse(toSettings.body); } catch (e) {}
      if (b.preview_defaults && b.preview_defaults.env && b.preview_defaults.env.MY_SECRET) symptom("wrangler preview secret put patched the Worker's Previews settings, not the Preview's latest deployment");
      broken("unexpected Worker PATCH body: " + toSettings.body);
    }
    if (!toDeployment) broken("no PATCH to the Preview deployment; exit " + status + "; requests " + JSON.stringify(seen.map((r) => r.method + " " + r.path)) + "; output " + out.slice(-800));
    let b;
    try { b = JSON.parse(toDeployment.body); } catch (e) { broken("deployment PATCH body is not JSON: " + toDeployment.body); }
    const s = b.env && b.env.MY_SECRET;
    if (!s || s.type !== "secret_text" || s.text !== "s3cret") broken("deployment PATCH body lacks the secret: " + toDeployment.body);
    if (toSettings) broken("wrangler also patched the Worker's Previews settings");
    if (status !== 0) broken("wrangler exited " + status + ": " + out.slice(-800));
    console.log("OK: wrangler preview secret put patched the Preview's latest deployment");
    process.exit(0);
  });
});

